def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my_last, op_last = history[-1]
    opp_d = sum(1 for _, o in history if o == 'D')
    opp_c = n - opp_d
    r5 = sum(1 for _, o in history[-5:] if o == 'D')
    r10 = sum(1 for _, o in history[-10:] if o == 'D')

    forgiven = 0
    punished = 0
    unprovoked = 0
    for i in range(1, n):
        pm, po = history[i - 1]
        oc = history[i][1]
        if pm == 'D' and po == 'C':
            if oc == 'C':
                forgiven += 1
            else:
                punished += 1
        if pm == 'C' and po == 'C' and oc == 'D':
            unprovoked += 1

    if n < 10:
        if op_last == 'D':
            if opp_d == n and n >= 2:
                return 'D'
            if opp_d <= 1:
                return 'C'
            if my_last == 'D' and opp_d <= max(2, n // 2):
                return 'C'
            if opp_d >= 3:
                return 'D'
            return 'C'
        return 'C'

    if n >= 60 and opp_d <= max(2, n // 10) and punished == 0 and (r5 == 0 or (my_last == 'D' and op_last == 'C')):
        if my_last == 'D' and op_last == 'C' and forgiven == 0:
            return 'C'
        return 'D'

    if opp_d * 3 >= n * 2 or (n >= 20 and r10 >= 8):
        return 'D'

    if op_last == 'C':
        if n >= 3:
            r = history[-3:]
            if r[0][0] == 'D' and r[1][0] == 'D' and r[2][0] == 'D' and r[0][1] == 'C' and r[1][1] == 'C' and r[2][1] == 'C':
                return 'D'

        if my_last == 'D' and forgiven > punished and opp_d <= max(3, n // 8) and r5 == 0:
            return 'D'

        if n >= 90 and my_last == 'D' and opp_d <= max(4, n // 12) and r5 <= 1:
            return 'D'

        return 'C'

    if n >= 3 and my_last == 'C' and op_last == 'D':
        if history[-2][0] == 'C' and history[-2][1] == 'D':
            return 'D'

        if history[-2][0] == 'D' and history[-2][1] == 'C':
            if opp_d <= max(3, n // 10) and r5 <= 2:
                return 'C'

    if my_last == 'D' and opp_c > opp_d and r5 <= 2:
        return 'C'

    if opp_d <= max(1, n // 10) and punished == 0:
        return 'C'

    if opp_d * 2 >= n:
        return 'D'

    if r5 >= 3:
        return 'D'

    if r10 >= 5:
        return 'D'

    if unprovoked > punished and opp_d >= 3:
        return 'D'

    return 'C'
